import React from "react";

const TransactionList = ({ transactions }) => {
  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-IN', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  return (
    <div style={{ 
      marginTop: "20px",
      background: "#ffffff",
      borderRadius: "16px",
      padding: "24px",
      boxShadow: "0 4px 20px rgba(0, 0, 0, 0.08)"
    }}>
      <h3 style={{
        color: "#2c3e50",
        fontSize: "24px",
        marginBottom: "24px",
        fontWeight: "600"
      }}>Transactions</h3>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {transactions.map((t, index) => (
          <li 
            key={index} 
            style={{ 
              margin: "16px 0",
              padding: "16px",
              backgroundColor: t.type === "income" ? "#e8f6f1" : "#fef1f2",
              borderRadius: "12px",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              transition: "transform 0.2s ease",
              cursor: "pointer",
              ":hover": {
                transform: "translateY(-2px)"
              }
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
              <div style={{ 
                width: "40px",
                height: "40px",
                borderRadius: "50%",
                backgroundColor: t.type === "income" ? "#00b894" : "#ff7675",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                color: "white",
                fontSize: "20px",
                fontWeight: "bold"
              }}>
                {t.type === "income" ? "+" : "-"}
              </div>
              <div style={{ display: "flex", flexDirection: "column" }}>
                <span style={{ 
                  fontWeight: "600",
                  color: "#2d3436",
                  fontSize: "16px",
                  marginBottom: "4px"
                }}>
                  {t.category}
                </span>
                {t.description && (
                  <span style={{ 
                    color: "#636e72",
                    fontSize: "14px"
                  }}>
                    {t.description}
                  </span>
                )}
                <span style={{ 
                  color: "#b2bec3",
                  fontSize: "12px",
                  marginTop: "4px"
                }}>
                  {formatDate(t.date)}
                </span>
              </div>
            </div>
            <div style={{
              fontWeight: "600",
              color: t.type === "income" ? "#00b894" : "#ff7675",
              fontSize: "18px"
            }}>
              {t.type === "income" ? "+" : "-"}₹{t.amount}
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default TransactionList;
